<?php

namespace App\Actions\ExamNotices;

use App\Actions\StudyPlans\FindOrCreateSubject;
use App\Actions\StudyPlans\FindOrCreateTopic;
use App\Models\ExamNotice;
use App\Models\User;
use Illuminate\Support\Facades\DB;

class ImportExamNoticeFromJson
{
    public function __construct(
        protected FindOrCreateSubject $findOrCreateSubject,
        protected FindOrCreateTopic $findOrCreateTopic,
    ) {}

    /**
     * Create an exam notice (and any missing catalog subjects/topics) from
     * a validated JSON payload, typically generated by an AI chat from the
     * official edital text.
     *
     * @param  array{name: string, exam_board: string, exam_date?: ?string, subjects: array<int, array{name: string, topics: array<int, string>}>}  $data
     */
    public function handle(array $data, User $actor): ExamNotice
    {
        return DB::transaction(function () use ($data, $actor) {
            $notice = new ExamNotice([
                'name' => $data['name'],
                'exam_board' => $data['exam_board'],
                'exam_date' => $data['exam_date'] ?? null,
            ]);

            $notice->forceFill(['owner_id' => $actor->id])->save();

            foreach ($data['subjects'] as $order => $subjectData) {
                $subject = $this->findOrCreateSubject->handle($subjectData['name'], $actor);

                $examSubject = $notice->examSubjects()->create([
                    'subject_id' => $subject->id,
                    'order' => $order,
                ]);

                foreach ($subjectData['topics'] as $topicOrder => $topicName) {
                    $topic = $this->findOrCreateTopic->handle($topicName, $subject);

                    $examSubject->examTopics()->create([
                        'topic_id' => $topic->id,
                        'order' => $topicOrder,
                    ]);
                }
            }

            return $notice;
        });
    }
}
